1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
5	
6	/**
7	 * Global portal search, powering the ⌘K palette / top-bar "Search anything".
8	 *
9	 * Searches across everything a caller can reach — servers, hosting plans,
10	 * hosting accounts, websites, mailboxes (email), domains and tickets — plus, for
11	 * admins, customers. Every result carries a `type` (for grouping + an icon) and a
12	 * ready-to-navigate `href` that jumps straight to the item.
13	 *
14	 * SCOPING is the security boundary and is applied per model:
15	 *   • Customers see ONLY their own rows (`userId` / relation scoped).
16	 *   • Admins see ACROSS accounts, and their result links point at the /admin
17	 *     equivalents.
18	 * Catalog rows (hosting plans) are the one non-owned type: everyone may see the
19	 * active plans; admins additionally see inactive ones.
20	 *
21	 * The response is `private, no-store` because for an admin it contains other
22	 * customers' hostnames, emails and ticket subjects — a shared cache keyed on the
23	 * `?q=` URL would otherwise replay one caller's results to the next.
24	 */
25	export async function GET(req: NextRequest) {
26	  const user = await currentUser();
27	  if (!user) {
28	    return NextResponse.json({ results: [] }, { status: 401, headers: NO_STORE_HEADERS });
29	  }
30	  const q = (req.nextUrl.searchParams.get("q") ?? "").trim();
31	  if (q.length < 2) return NextResponse.json({ results: [] }, { headers: NO_STORE_HEADERS });
32	
33	  const isAdmin = user.role === "ADMIN";
34	  // Ownership filter reused across every customer-owned model.
35	  const own = isAdmin ? {} : { userId: user.id };
36	  const like = { contains: q, mode: "insensitive" as const };
37	
38	  const results: { type: string; label: string; sub?: string; href: string }[] = [];
39	
40	  // Everything runs concurrently; each block fails soft so one bad table can't
41	  // blank the whole palette.
42	  const soft = <T,>(p: Promise<T>, fallback: T): Promise<T> => p.catch(() => fallback);
43	
44	  const [servers, plans, accounts, websites, mailboxes, domains, tickets, customers] =
45	    await Promise.all([
46	      // Servers (VPS + game). Match the hostname, the customer nickname, or the name.
47	      soft(
48	        db.server.findMany({
49	          where: { OR: [{ hostname: like }, { label: like }, { name: like }], ...own },
50	          include: { user: true },
51	          take: 6,
52	        }),
53	        [] as Array<{
54	          id: string;
55	          hostname: string;
56	          label: string | null;
57	          status: string;
58	          user: { email: string };
59	        }>,
60	      ),
61	      // Hosting plans (catalog — not owned). Customers see active plans only.
62	      soft(
63	        db.hostingPlan.findMany({
64	          where: {
65	            OR: [{ name: like }, { slug: like }, { tagline: like }],
66	            ...(isAdmin ? {} : { active: true }),
67	          },
68	          take: 4,
69	        }),
70	        [] as Array<{ id: string; name: string; slug: string; priceCents: number; active: boolean }>,
71	      ),
72	      // Hosting accounts. Match the primary domain or the jailed username.
73	      soft(
74	        db.hostingAccount.findMany({
75	          where: { OR: [{ primaryDomain: like }, { username: like }], ...own },
76	          include: { user: true },
77	          take: 5,
78	        }),
79	        [] as Array<{ id: string; primaryDomain: string; status: string; user: { email: string } }>,
80	      ),
81	      // Websites (VPS vhosts). Managed from their server's control panel, so the
82	      // result jumps to the owning server.
83	      soft(
84	        db.website.findMany({ where: { domain: like, ...own }, take: 5 }),
85	        [] as Array<{ id: string; domain: string; status: string; serverId: string }>,
86	      ),
87	      // Mailboxes (business email). Scoped through the subscription's owner.
88	      soft(
89	        db.mailbox.findMany({
90	          where: { address: like, ...(isAdmin ? {} : { subscription: { userId: user.id } }) },
91	          include: { subscription: { include: { user: true } } },
92	          take: 5,
93	        }),
94	        [] as Array<{ id: string; address: string; status: string; subscription: { user: { email: string } } }>,
95	      ),
96	      soft(
97	        db.domain.findMany({ where: { name: like, ...own }, take: 4 }),
98	        [] as Array<{ id: string; name: string; status: string }>,
99	      ),
100	      soft(
101	        db.ticket.findMany({ where: { subject: like, ...own }, take: 4 }),
102	        [] as Array<{ id: string; subject: string; status: string }>,
103	      ),
104	      // Customers — admin only.
105	      isAdmin
106	        ? soft(
107	            db.user.findMany({ where: { OR: [{ email: like }, { name: like }] }, take: 5 }),
108	            [] as Array<{ id: string; name: string; email: string }>,
109	          )
110	        : Promise.resolve([] as Array<{ id: string; name: string; email: string }>),
111	    ]);
112	
113	  for (const s of servers) {
114	    results.push({
115	      type: "server",
116	      label: s.label || s.hostname,
117	      sub: isAdmin ? `${s.user.email} · ${s.status.toLowerCase()}` : s.status.toLowerCase(),
118	      href: isAdmin ? `/admin/servers/${s.id}` : `/dashboard/servers/${s.id}`,
119	    });
120	  }
121	
122	  for (const p of plans) {
123	    results.push({
124	      type: "hosting",
125	      label: p.name,
126	      sub: `hosting plan · $${(p.priceCents / 100).toFixed(2)}/mo${!p.active ? " · inactive" : ""}`,
127	      href: isAdmin ? "/admin/hosting" : "/dashboard/hosting",
128	    });
129	  }
130	
131	  for (const a of accounts) {
132	    results.push({
133	      type: "hosting",
134	      label: a.primaryDomain,
135	      sub: isAdmin ? `${a.user.email} · ${a.status.toLowerCase()}` : `hosting · ${a.status.toLowerCase()}`,
136	      href: isAdmin ? "/admin/hosting" : `/dashboard/hosting/${a.id}`,
137	    });
138	  }
139	
140	  for (const w of websites) {
141	    results.push({
142	      type: "website",
143	      label: w.domain,
144	      sub: `website · ${w.status.toLowerCase()}`,
145	      href: isAdmin ? `/admin/servers/${w.serverId}` : `/dashboard/servers/${w.serverId}`,
146	    });
147	  }
148	
149	  for (const m of mailboxes) {
150	    results.push({
151	      type: "email",
152	      label: m.address,
153	      sub: isAdmin ? `${m.subscription.user.email} · ${m.status.toLowerCase()}` : `mailbox · ${m.status.toLowerCase()}`,
154	      href: isAdmin ? "/admin/mailboxes" : "/dashboard/email",
155	    });
156	  }
157	
158	  for (const d of domains) {
159	    results.push({
160	      type: "domain",
161	      label: d.name,
162	      sub: d.status.toLowerCase(),
163	      href: isAdmin ? "/admin/domains" : `/dashboard/domains/${d.id}`,
164	    });
165	  }
166	
167	  for (const t of tickets) {
168	    results.push({
169	      type: "ticket",
170	      label: t.subject,
171	      sub: t.status.toLowerCase(),
172	      href: isAdmin ? `/admin/support/${t.id}` : `/dashboard/support/${t.id}`,
173	    });
174	  }
175	
176	  for (const u of customers) {
177	    results.push({ type: "customer", label: u.name, sub: u.email, href: `/admin/users/${u.id}` });
178	  }
179	
180	  return NextResponse.json({ results: results.slice(0, 30) }, { headers: NO_STORE_HEADERS });
181	}
