17	// Parallel /admin <-> /staff routes for the tools GRANTABLE_AREAS
18	// (lib/staff-grants.ts) exposes to both portals. An ADMIN account previewing
19	// /staff still receives their real ADMIN-scoped notifications (new tickets,
20	// replies, etc.) and their href is baked in as /admin/... at write time —
21	// correct when viewed from the admin portal, but the staff subdomain can't
22	// reach /admin/* at all (see middleware.ts's portal isolation), so clicking
23	// one there 404'd. Confirmed live 2026-09-03. Rewriting the DISPLAY href by
24	// portal (not the stored Notification.href, which stays correct for the
25	// admin side) fixes it without touching every notification-creation call
26	// site — same fix applies to AdminIndicators' two hardcoded links below.
27	const ADMIN_TO_STAFF_HREF: Record<string, string> = {
28	  "/admin/support": "/staff/support",
29	  "/admin/chat": "/staff/chat",
30	  "/admin/reddit": "/staff/reddit",
31	  "/admin/inbox": "/staff/inbox",
32	  "/admin/clients-basic": "/staff/clients",
33	  "/admin/tasks": "/staff/tasks",
34	};
35	
36	export function portalHref(href: string, isStaffPortal: boolean): string {
37	  if (!isStaffPortal) return href;
38	  for (const [adminPrefix, staffPrefix] of Object.entries(ADMIN_TO_STAFF_HREF)) {
39	    if (href === adminPrefix || href.startsWith(`${adminPrefix}/`)) {
40	      return staffPrefix + href.slice(adminPrefix.length);
41	    }
42	  }
43	  return href;
44	}
45	
46	export type NavChild = { label: string; href: string; badge?: number };
47	export type NavItem = {
48	  label: string;
49	  href: string;
50	  /**
51	   * Leading icon (key into the `icons` map below). Both portals supply one for
52	   * every item; the link degrades to its initial if a key is ever missing.
53	   */
54	  icon?: string;
55	  badge?: number;
56	  /**
57	   * Secondary destinations that live *behind* this entry. The sidebar never
58	   * expands them — the admin portal surfaces them as in-page sub-tabs (see
59	   * components/admin/SubTabs.tsx). They exist here so the sidebar row stays
60	   * highlighted while you're on one of them, and so ⌘K can still jump straight
61	   * to any of them. Customer nav passes none and renders exactly as before.
62	   */
63	  children?: NavChild[];
64	  /** Static uppercase text pill shown in place of a numeric badge (e.g. "FREE"). */
65	  tag?: string;
66	};
67	export type NavSection = {
68	  /**
69	   * Stable key for the section, used to persist its collapsed/expanded state
70	   * (admin portal only — see `collapsedGroups` below). Sections without one
71	   * (the customer portal doesn't supply it) fall back to their index, so they
72	   * still render correctly but just never persist a collapse a user never
73	   * gets the option to make outside the admin ops portal.
74	   */
75	  key?: string;
76	  label?: string;
77	  items: NavItem[];
78	};
79	
80	export type ShellNotification = {
81	  id: string;
82	  title: string;
83	  body?: string | null;
84	  href?: string | null;
85	  readAt: string | null;
86	  createdAt: string;
87	};
