146	      <path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3" />
147	    </>
148	  ),
149	  /* Support desk (tickets + live chat + feedback). */
150	  lifebuoy: (
151	    <>
152	      <circle cx="12" cy="12" r="9" />
153	      <circle cx="12" cy="12" r="3.6" />
154	      <path d="M5.6 5.6l3.9 3.9M14.5 14.5l3.9 3.9M18.4 5.6l-3.9 3.9M9.5 14.5l-3.9 3.9" />
155	    </>
