46	      {servers.length === 0 ? (
47	        <EmptyState
48	          title="No servers yet"
49	          sub="Deploy your first NVMe-backed VPS — it takes under two minutes from click to SSH."
50	          action={
51	            <DeployButton href="/dashboard/deploy">Deploy your first server</DeployButton>
52	          }
53	        />
54	      ) : (
55	        <ServersList servers={rows} />
56	      )}
