36	  // HostingAccountView doesn't carry. Real progress label: see
37	  // lib/provisioning-step.ts — while PENDING/PROVISIONING it's the worker's own
38	  // per-command-group label; once ACTIVE it's whichever content task (most
39	  // commonly a WordPress install queued at order time) is still running.
40	  const [raw, stepLabel] = await Promise.all([
41	    db.hostingAccount.findUnique({
42	      where: { id: account.id },
43	      select: { sftpPasswordEnc: true, node: { select: { publicIp: true, hostnameFqdn: true } } },
44	    }),
45	    hostingProvisioningStep(account.id),
46	  ]);
47	  const sftpPassword = raw?.sftpPasswordEnc ? decryptSecret(raw.sftpPasswordEnc) : null;
48	  const sftpHost = raw?.node?.hostnameFqdn || raw?.node?.publicIp || null;
49	  // True while a real follow-on step (e.g. that WordPress install) is still
50	  // running even though the account itself already flipped ACTIVE — see
51	  // ProvisioningOverlay's `liveStepActive` prop doc for why this is safe against
52	  // hijacking the screen for a later, casual install.
53	  const installStepActive = account.status === "ACTIVE" && stepLabel !== null;
54	
55	  const overlay = (
56	    <ProvisioningOverlay
57	      serverId={account.id}
58	      status={account.status}
59	      transitional={transitional}
60	      justPaid={purchase === "1"}
61	      provisionError={account.error}
62	      productLabel="hosting account"
63	      hostname={account.primaryDomain}
64	      // Shared Hosting has no VPS-style "connect" address — the closest analogue
65	      // is the SFTP login, so that's what's shown here; the live site URL is a
66	      // separate `extraInfo` row below rather than overloading this field.
67	      connectAddress={sftpHost ? `sftp://${account.username}@${sftpHost}` : null}
68	      planName={account.planName}
69	      osName={null}
70	      rootPassword={sftpPassword}
71	      rootPasswordLabel="SFTP password"
72	      extraInfo={[
73	        { label: "SFTP username", value: account.username },
74	        { label: "Website", value: `https://${account.primaryDomain}/`, href: `https://${account.primaryDomain}/` },
75	      ]}
76	      readyStatus="ACTIVE"
77	      liveStep={stepLabel}
78	      liveStepActive={installStepActive}
79	      dashboardHref={`/dashboard/hosting/${account.id}`}
80	    />
81	  );
82	
83	  return (
84	    <div>
85	      {overlay}
86	      {(transitional || installStepActive) && <AutoRefresh />}
87	
88	      <div className="mb-6">
89	        <div className="flex flex-wrap items-center gap-3">
90	          <h1 className="page-title">{account.primaryDomain}</h1>
91	          <StatusDot status={account.status} />
