96	          <Badge tone="slate">PHP {account.phpVersion}</Badge>
97	          <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
98	        </div>
99	      </div>
100	
101	      {transitional && (
102	        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
103	          Your account is being set up — this usually takes under a minute. This page refreshes automatically.
104	        </div>
105	      )}
106	
107	      <HostingTabs account={account} initialTab={tab} initialPath={path} />
