17	export default async function RegisterDomainPage({
18	  searchParams,
19	}: {
20	  searchParams: Promise<{ domain?: string }>;
21	}) {
22	  const user = await requireUser();
23	  const { domain: raw } = await searchParams;
24	  const domain = (raw ?? "").toLowerCase().trim();
25	  const valid = DOMAIN_RE.test(domain);
26	  const configured = registrarConfigured();
27	
28	  if (!configured) {
29	    return (
30	      <div className="space-y-6">
31	        <PortalHero variant="domains" title="Register domain" />
