45	  // Live availability + price for the pre-selected domain (best-effort). Mapped
46	  // into the shared DomainCheckResult shape (status + sld/tld) the wizard uses.
47	  let initialCheck: DomainCheckResult | null = null;
48	  if (valid) {
49	    try {
50	      const [check] = await checkDomains([domain]);
51	      if (check) {
52	        const dot = check.domain.indexOf(".");
53	        const available = check.available && check.priceCents !== null;
54	        initialCheck = {
55	          domain: check.domain,
56	          sld: dot > 0 ? check.domain.slice(0, dot) : check.domain,
57	          tld: dot > 0 ? check.domain.slice(dot + 1) : "",
58	          status: available ? "available" : "taken",
59	          available,
60	          premium: check.premium,
61	          priceCents: available ? check.priceCents : null,
62	          renewCents: available ? check.renewCents : null,
63	        };
64	      }
65	    } catch {
66	      /* registrar briefly unreachable — the wizard can re-check client-side */
67	    }
68	  }
