6	import TeamManager, { type OrgView } from "@/components/customer/TeamManager";
7	
8	export const dynamic = "force-dynamic";
9	
10	export default async function TeamPage() {
11	  const user = await requireUser();
12	
13	  // Every org the user owns or belongs to (owner always has an OWNER membership).
14	  const memberships = await db.membership.findMany({
15	    where: { userId: user.id },
16	    orderBy: { createdAt: "asc" },
17	    include: {
18	      org: {
19	        include: {
20	          owner: { select: { id: true, name: true } },
21	          members: {
22	            orderBy: { createdAt: "asc" },
23	            include: { user: { select: { id: true, name: true, email: true } } },
24	          },
25	        },
26	      },
27	    },
28	  });
29	
30	  const orgs: OrgView[] = memberships.map((m) => {
31	    const org = m.org;
32	    const iAdminister = canAdministerOrg(m.role);
33	    return {
34	      id: org.id,
35	      name: org.name,
36	      createdAgo: timeAgo(org.createdAt),
37	      ownerName: org.owner.name,
38	      myRole: m.role,
39	      canAdminister: iAdminister,
40	      isOwner: org.ownerId === user.id,
41	      members: org.members.map((mem) => {
42	        const isSelf = mem.userId === user.id;
43	        return {
44	          // The client is never given a co-member's `userId`. Combined with an
45	          // email address that was the whole attack: `verifyTotpForUser`
46	          // (QA-PRELAUNCH P0-2) took an arbitrary userId with no auth and no
47	          // rate limit, and this page used to hand one over for every member of
48	          // every org the viewer was in — an org they could have been added to
49	          // without consenting. The oracle is fixed; the ids still have no
50	          // business crossing to the browser, so role/remove are keyed by
51	          // membership id instead (see lib/actions-teams.ts).
52	          membershipId: iAdminister ? mem.id : null,
53	          name: mem.user.name,
54	          // Addresses go only to viewers entitled to them: someone who can
55	          // actually administer membership, plus your own row. A rank-and-file
56	          // MEMBER sees names, not a harvestable address list.
57	          email: iAdminister || isSelf ? mem.user.email : null,
58	          role: mem.role,
59	          isOwner: mem.userId === org.ownerId,
60	          isSelf,
61	          joinedAgo: timeAgo(mem.createdAt),
62	        };
63	      }),
64	    };
65	  });
66	
67	  return (
68	    <div className="space-y-6">
69	      <PortalHero
70	        variant="team"
71	        title="Team"
72	        sub="Create organizations and invite teammates to your shared roster."
73	      />
74	      <TeamManager orgs={orgs} />
75	    </div>
76	  );
77	}
